const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fromDate=s=>new Date(`${s}T12:00:00`);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let profile=defaultProfile(),equipment={},extraExercise='';
let scope=localStorage.getItem('form-local-scope')||'guest',accountEpoch=0;
if(!/^account-[a-zA-Z0-9-]+$/.test(scope))scope='guest';
let cachedAccount=read('form-last-account',null);
let cloudReady=false,emailReady=false,googleReady=false,auth=null,authMode='signin',authMessage='';
