let resetToken=entryParams.get('flow')==='reset'?entryParams.get('token'):null;
if(entryParams.get('flow')==='google'&&entryParams.has('error')){authMessage=entryParams.get('error')==='account_not_linked'?'Verify your existing account email first, then try Google again.':'Google sign-in did not finish. Try again or use your email and PIN.';history.replaceState(null,'',location.pathname+'#settings');}
else if(entryParams.has('token')||entryParams.has('error')||entryParams.has('verified')||entryParams.has('flow')){authMessage=entryParams.has('error')?'This email link is invalid or expired. Request another link.':resetToken?'Choose a new PIN below.':'Email link processed. Sign in to continue.';history.replaceState(null,'',location.pathname+'#settings');}
// Old Supabase session tokens are no longer used.
sessionStorage.removeItem('form-auth');
let records=[],tab='today',selected=dateKey(),month=new Date(new Date().getFullYear(),new Date().getMonth(),1),exerciseFilter='',busy=false,lastSync=null,timerEnd=0,wakeLock,learnSection='basics',trendExercise='';
const patterns=[['push','Push'],['pull','Pull'],['legs','Legs'],['core','Core']];
const active=()=>records.filter(r=>!r.deleted);
const dayRecords=(date=selected)=>active().filter(r=>r.date===date);
const sets=(id,date=selected)=>dayRecords(date).filter(r=>r.type==='set'&&r.data.exercise===id);
const plan=(date=selected)=>{const p=dayPlan(profile,records,date),session=sessionFor(active(),date);return !p.skipped&&Array.isArray(session.exerciseIds)?{...p,ids:session.exerciseIds.filter(id=>exercises[id])}:p;};
const sum=(rows,key)=>rows.reduce((n,r)=>n+(Number(r.data[key])||0),0);
const badge=t=>`<span class="badge">${esc(t)}</span>`;
const button=(text,action,cls='')=>`<button class="btn ${cls}" data-action="${action}">${text}</button>`;
const trainingStage=()=>sessionFor(active(),selected).stage||stageOn(profile,selected);
const target=id=>sessionSetGoal(id,trainingStage(),sessionFor(active(),selected));
const current=()=>currentExercise(plan().ids,active(),selected,trainingStage());
const coach=()=>coachState(active(),selected,plan().ids,trainingStage());
const info=(id,text)=>`<button type="button" class="term" data-action="term:${id}" aria-label="What is ${esc(basics.find(b=>b.id===id).term)}?">${text?`${text} `:''}<span aria-hidden="true">?</span></button>`;
const dayTools=p=>[...new Set(p.ids.flatMap(id=>exercises[id].tools))];
const sceneFor=p=>p.skipped?'recovery':p.kind==='Recovery'?'recovery':p.kind==='Light day'?'cardio':p.ids.some(id=>exercises[id].pattern==='legs')?'lower':'upper';
const lastDays=n=>Array.from({length:n},(_,i)=>{const d=new Date();d.setDate(d.getDate()-n+1+i);return dateKey(d);});
const sceneImage=p=>({upper:'./img/coach/press-steps.webp',lower:'./img/coach/squat-steps.webp',cardio:'./img/generated/walk.webp',recovery:'./img/basics/rest.webp'}[sceneFor(p)]);
function toolStrip(ids){return `<div class="tools">${ids.map(t=>`<button class="tool" data-action="tool:${t}"><img src="${tools[t].image}" alt="" width="72" height="72" loading="lazy"><span>${tools[t].name}</span></button>`).join('')}</div>`;}
const mediaFor=key=>{const [kind,id]=key.split('.');return kind==='tool'?tools[id]:exercises[id];};
function video(key){const m=mediaFor(key);if(m.externalVideo)return `<div class="video"><a class="btn secondary" href="${esc(m.externalVideo)}" target="_blank" rel="noopener noreferrer">Watch reference video · FITTR ↗</a><small>${esc(m.videoNote)}</small></div>`;return `<div class="video">${isOnline()?(key.startsWith('ex.')?button('▶ Watch technique video','play:'+key):`<button class="video-poster" data-action="play:${key}" aria-label="Play video: ${esc(m.videoLabel)}"><img src="https://i.ytimg.com/vi/${m.youtube}/hqdefault.jpg" alt="" loading="lazy"><span class="play" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7Z"/></svg></span></button>`):'<div class="video-offline">Video needs an internet connection. The illustration and technique steps below work offline.</div>'}<details class="video-reference"><summary>Video reference & variation</summary><small>${esc(m.videoLabel)} · <a href="https://www.youtube.com/watch?v=${m.youtube}" target="_blank" rel="noopener noreferrer">Open on YouTube ↗</a></small>${m.videoNote?`<p><small>${esc(m.videoNote)}</small></p>`:''}${m.additionalVideos?.length?`<details><summary>Other Indian trainer references</summary>${m.additionalVideos.map(ref=>`<p><a href="https://www.youtube.com/watch?v=${ref.youtube}" target="_blank" rel="noopener noreferrer">${esc(ref.label)} ↗</a><br><small>${esc(ref.note)}</small></p>`).join('')}</details>`:''}</details></div>`;}
function photoFigure(p,alt){if(!p)return '<p class="photo-missing"><small>Reference unavailable. Open the demonstration video.</small></p>';return `<figure class="ref-photo"><img src="${esc(p.url)}" alt="${esc(p.kind==='video'?alt+' · original video preview':alt)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" data-reference="true"><figcaption>${p.kind==='video'?'Original demonstration preview':'Reference photo'}: ${esc(p.author)} · ${esc(p.license)} · <a href="${esc(p.page)}" target="_blank" rel="noopener noreferrer">${p.kind==='video'?'Watch original video':'Wikimedia Commons'} ↗</a></figcaption></figure>`;}
function facts(id){const e=exercises[id],rows=[['Muscles',e.muscles],['Pattern',e.pattern==='cardio'?'Cardio':patterns.find(p=>p[0]===e.pattern)[1]],['Sets × reps',id==='walk'?`1 bout · ${e.reps}`:`${target(id)} × ${id==='pushup'?'10':e.reps}`],['Rest',e.rest],['Tempo',e.tempo],['Effort',e.rir]];return `<dl class="facts">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;}
function emptyChart(kind,text){const shapes={bar:[30,52,24,64,40,70,34].map((h,i)=>`<rect x="${22+i*40}" y="${92-h}" width="24" height="${h}" rx="4" fill="#efedf5"/>`).join(''),line:'<polyline points="20,80 70,62 120,70 170,44 220,52 270,30" fill="none" stroke="#e3d8f8" stroke-width="4" stroke-dasharray="8 7" stroke-linecap="round"/>',ring:'<circle cx="160" cy="52" r="36" fill="none" stroke="#efedf5" stroke-width="12"/><path d="M160 16a36 36 0 0 1 34 24" fill="none" stroke="#e3d8f8" stroke-width="12" stroke-linecap="round"/>',heat:Array.from({length:36},(_,i)=>`<rect x="${40+Math.floor(i/4)*26}" y="${10+(i%4)*21}" width="20" height="17" rx="3" fill="${i%5?'#f3f2f7':'#e3d8f8'}"/>`).join('')};return `<div class="empty-chart"><svg viewBox="0 0 300 100" role="img" aria-label="Empty chart placeholder">${shapes[kind]}<path d="M14 96H290" stroke="#e7e7ee"/></svg><p>${text}</p></div>`;}
function setBars(rows,cardio){if(!rows.length)return '';const key=cardio?'minutes':'reps',max=Math.max(...rows.map(r=>Number(r.data[key])||0),1);return `<div class="set-bars" role="img" aria-label="Logged ${cardio?'bouts':'sets'}: ${rows.map((r,i)=>`${cardio?'bout':'set'} ${i+1}, ${esc(r.data[key])} ${cardio?'minutes':'reps'}${cardio?'':` at ${esc(r.data.weight)} kg`}`).join('; ')}">${rows.map((r,i)=>`<div><i style="height:${Math.max(6,(Number(r.data[key])||0)/max*66)}%" class="${r.data.symptom?'warn':''}"></i><small>${cardio?`${esc(r.data.minutes)}′`:`${esc(r.data.reps)}×${esc(r.data.weight)}`}</small><small>${cardio?'Bout':'Set'} ${i+1}</small></div>`).join('')}</div>`;}
function lastSession(id){const prev=active().filter(r=>r.type==='set'&&r.data.exercise===id&&r.date<selected);if(!prev.length)return '<small>First time logging this movement — start light.</small>';const date=prev.reduce((a,r)=>r.date>a?r.date:a,'');return `<small>Last session ${esc(date)}: ${prev.filter(r=>r.date===date).map(r=>r.data.minutes?`${esc(r.data.minutes)} min`:`${esc(r.data.reps)} × ${esc(r.data.weight)} kg`).join(' · ')}</small>`;}
function showDialog(html,label){let d=$('#info-dialog');if(!d){d=document.createElement('dialog');d.id='info-dialog';document.body.append(d);}d.setAttribute('aria-label',label);d.innerHTML=`${html}<form method="dialog"><button class="btn">Close</button></form>`;d.showModal();}
function basicReference(id){const exercise=basicsExercise(id);return `<p><small>Exercise example · watch the movement, then apply the guidance above.</small></p>`+video('ex.'+(exercise||'press'));}
function termDialog(id){const b=basics.find(x=>x.id===id);showDialog(`<div class="eyebrow">Training basics</div><h2>${b.term}</h2><p><strong>${b.short}</strong></p>${basicsVisual(b.id,`${b.term}: ${b.short}`)}<p>${b.detail}</p>${basicReference(b.id)}`,b.term);}
function toolDialog(id){const t=tools[id],used=Object.keys(exercises).filter(x=>exercises[x].tools.includes(id));showDialog(`<div class="eyebrow">Equipment</div><h2>${t.name}</h2>${toolDetail(id,used)}`,t.name);}
function toolDetail(id,used){const t=tools[id],local=t.image;return `<img class="tool-img" src="${local}" alt="${esc(t.name)} equipment reference" width="240" height="240" loading="lazy">${t.imageKind==='generated'?'<small>AI-generated equipment teaching image · confirm your machine with gym staff.</small>':''}${photoFigure(t.photo,`${t.name} in a gym`,local)}${video('tool.'+id)}<p>${t.use}</p><ol>${t.setup.map(s=>`<li>${s}</li>`).join('')}</ol><div class="notice">${t.safety}</div><small>Used for: ${used.map(x=>exercises[x].name).join(', ')}</small>`;}
function toast(text){$('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=text;document.body.append(d);setTimeout(()=>d.remove(),4500);}
function heading(kicker,title,subtitle=''){return `<div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="muted">${subtitle}</p>`;}
function exerciseCard(id,runner=false){const e=exercises[id],logged=sets(id),goal=target(id);return `<article class="card exercise" id="exercise-${runner?'train':'learn'}-${id}" tabindex="-1"><div class="row"><img class="ex-thumb" src="${e.img}" alt="" width="56" height="56" loading="lazy"><div class="grow"><h3>${e.name}</h3><small>${e.muscles}</small></div>${badge(id==='walk'?'Easy pace':`${goal} sets × ${id==='pushup'?'10':e.reps} reps`)}</div>${id==='walk'?'':`<p class="terms">${info('set','Set')}${info('rep','Rep')}${info('rir','RIR')}${info('rest','Rest')}</p>`}${runner?`<div class="bar"><i style="width:${Math.min(100,logged.length/goal*100)}%"></i></div><small>${id==='pushup'?`${sum(logged,'reps')} / 30 reps · `:''}${logged.length} of ${goal} ${id==='walk'?'bout':'sets'} logged · start light, keep 2–3 clean reps in reserve</small>${setBars(logged,id==='walk')}<p>${lastSession(id)}</p>`:''}${equipmentGuide(id,runner)}<details ${!runner||!logged.length?'open':''}><summary>Full exercise guide · video, photos & technique</summary><p><small>${e.imageKind==='equipment'?'Equipment reference photo.':'AI-generated start/end teaching reference.'} Follow the real demonstration for technique.</small></p><img class="ex-hero" src="${e.img}" alt="Teaching photos of ${esc(e.name.toLowerCase())}" width="480" height="358" loading="lazy">${video('ex.'+id)}${photoFigure(e.photo,`${e.name} reference photo`,e.img)}${facts(id)}<h4>Setup</h4><p>${e.setup}</p><h4>Step by step</h4><ol>${e.cues.map(c=>`<li>${c}</li>`).join('')}</ol><p><strong>Breathing:</strong> ${e.breathing}</p><div class="notice"><strong>Common mistake:</strong> ${e.mistake}</div><div class="notice"><strong>Stop if:</strong> ${e.stop}</div><p><strong>How to progress:</strong> ${e.progression}</p><small>Alternative: ${e.alternative}</small></details>${runner?`${exerciseNavigation(id)}${logged.map(r=>`<div class="list-item row"><span>${r.data.minutes?`${esc(r.data.minutes)} min`:`${esc(r.data.reps)} reps · ${esc(r.data.weight)} kg ${r.data.assistance?'assistance':''}`}<br><small>${esc(r.data.symptom?'Symptoms reported — no progression':`RIR ${r.data.rir} · ${r.data.form}`)}</small></span>${button('Undo',`delete:${r.id}`,'secondary small')}</div>`).join('')}<form data-form="set" data-exercise="${id}"><fieldset ${logged.some(r=>r.data.symptom)?'disabled':''}>${id==='walk'?'<label>Minutes</label><input name="minutes" type="number" min="1" max="300" required value="20">':`<div class="fields"><div><label>Reps</label><input name="reps" type="number" min="1" max="500" required></div><div><label>Weight (kg; 0 = bodyweight)</label><input name="weight" type="number" min="0" max="1000" step="0.5" required value="0"></div><div><label>How many more clean reps could you do?</label><select name="rir" required><option value="">Choose after your set</option><option>3</option><option>2</option><option>1</option><option>0</option><option>4</option></select></div></div><label>How did your technique feel?</label><select name="form" required><option value="">Choose after your set</option><option value="good">Good / controlled</option><option value="uncertain">Unsure — ask for a check</option><option value="breakdown">Form broke down</option></select><label><input type="checkbox" name="assistance" ${id==='assisted'?'checked':''}> Weight is assistance (lower can mean harder)</label>`}<label><input type="checkbox" name="symptom"> Pain or tingling occurred — stop this movement</label><label>Optional note</label><input name="note" maxlength="300" placeholder="Seat setting, machine, or how it felt"><p><button class="btn" type="submit">Save ${id==='walk'?'activity':'set'} & continue</button></p></fieldset></form>`:''}</article>`;}

function jumpExercise(id){const el=$(`#exercise-${tab==='train'?'train':'learn'}-${id}`);if(el){el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});el.focus({preventScroll:true});}}
function exerciseNavigation(){return '';}
function sessionNavigation(p){return `<section class="card"><div class="eyebrow">${esc(selected)} · Your session</div><h2>Exercise guide & navigation</h2><p>Choose a movement to see its illustration, original reference, video and steps before logging.</p><div class="session-links">${p.ids.map((id,i)=>button(`${i+1}. ${esc(exercises[id].name)}`,'jump:'+id,'secondary')).join('')}</div>${p.ids.length?'':button('Choose a training day','calendar','secondary')}</section>`;}
function coreGuide(p){return `<section class="card"><div class="eyebrow">Your abs & core goal</div><h2>Build control, then difficulty</h2><p>Tuesday and Friday include dead bugs. Begin with short leg reaches, 2 sets of 6–10 reps per side. Breathe throughout and keep your trunk steady.</p><ol><li>Start with bent-knee reaches or heel slides if needed.</li><li>Build controlled reps toward 10 per side.</li><li>Once both sets feel steady and symptom-free across sessions, lengthen the reach or add the opposite arm. Change one thing at a time.</li></ol><p>Keep recovery between core sessions. Consistent strength training, meals, sleep and overall body composition also influence visible abs; there is no fixed appearance deadline.</p>${p.ids.includes('deadbug')?button('View today’s dead bug guide','jump:deadbug','secondary'):button('See core demonstration','guide:deadbug','secondary')}<p><a href="https://www.nasm.org/resource-center/blog/training/core-training-programming" target="_blank" rel="noopener noreferrer">Core training guidance · NASM ↗</a></p></section>`;}
const routeTabs=['today','train','learn','food','calendar','progress','settings'];
let restoringNavigation=false;
function navigationState(){return {tab,selected,learnSection,extraExercise};}
function syncNavigation(){if(restoringNavigation)return;const state=navigationState(),previous=history.state;if(previous&&JSON.stringify(previous.route)===JSON.stringify(state))return;const url=`#${tab}?date=${selected}&section=${learnSection}`;if(previous?.route)history.replaceState({...previous,scrollY:window.scrollY},'');history[previous?.route?'pushState':'replaceState']({route:state,scrollY:0,canGoBack:!!previous?.route},'',url);}
function restoreRoute(state){if(!state||!routeTabs.includes(state.tab))return;tab=state.tab;if(/^\d{4}-\d{2}-\d{2}$/.test(state.selected)&&!Number.isNaN(fromDate(state.selected).getTime()))selected=state.selected;learnSection=['basics','equipment','exercises'].includes(state.learnSection)?state.learnSection:'basics';extraExercise=exercises[state.extraExercise]?state.extraExercise:'';month=new Date(fromDate(selected).getFullYear(),fromDate(selected).getMonth(),1);}
function routeFromURL(){const [route,query]=location.hash.slice(1).split('?'),params=new URLSearchParams(query);return {tab:routeTabs.includes(route)?route:'today',selected:params.get('date')||dateKey(),learnSection:params.get('section')||'basics'};}
restoreRoute({...history.state?.route,...routeFromURL()});
addEventListener('popstate',event=>{restoreRoute(event.state?.route||routeFromURL());restoringNavigation=true;render();restoringNavigation=false;history.replaceState({...event.state,route:navigationState(),scrollY:event.state?.scrollY||0},'');window.scrollTo(0,event.state?.scrollY||0);});
addEventListener('hashchange',()=>{const route=routeFromURL();if(route.tab===tab&&route.selected===selected&&route.learnSection===learnSection)return;restoreRoute(route);restoringNavigation=true;render();restoringNavigation=false;history.replaceState({route:navigationState(),scrollY:0},'');window.scrollTo(0,0);});

const navPaths={today:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',train:'<path d="M6 8v8M3 9v6M18 8v8M21 9v6M6 12h12"/>',food:'<path d="M5 3v6m3-6v6M5 6h3M6.5 9v12M17 3c-3 3-3 8 0 9h2V3Zm2 9v9"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18M7 14h2m4 0h2m-8 3h2"/>',progress:'<path d="M3 3v18h18M7 16v-4m5 4V8m5 8V5"/>',learn:'<path d="M4 19V5a2 2 0 0 1 2-2h14v14H6a2 2 0 0 0-2 2Zm0 0a2 2 0 0 0 2 2h14"/><path d="M9 7h7M9 11h5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z"/>'};
function navIcon(id){return `<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true">${navPaths[id]}</svg>`;}
function weekStrip(){const start=new Date();start.setDate(start.getDate()-((start.getDay()+6)%7));return `<div class="week-strip" aria-label="This week">${Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=dateKey(d),done=dayRecords(key).some(r=>r.type==='session'&&r.data.status==='complete');return `<button data-action="week:${key}" class="${key===dateKey()?'current':''} ${done?'done':''}" aria-label="${key}, ${plan(key).name}${done?', completed':''}"><span>${d.toLocaleDateString(undefined,{weekday:'short'})}</span><strong>${d.getDate()}</strong><span class="dot">${done?'✓':' '}</span></button>`;}).join('')}</div>`;}
function workoutNextLabel(){const state=coach();return state.phase==='warmup'?'Start warm-up':state.phase==='set'?'Continue '+exercises[state.id].name+' · Set '+(sets(state.id).length+1):state.phase==='rest'?'Continue your rest':state.phase==='stop'?'Review your symptom stop':state.phase==='cooldown'?'Continue cooldown':'Review your workout';}
function today(){
 const p=plan(),session=sessionFor(active(),selected),complete=session.status==='complete',rest=p.skipped||!p.ids.length,info=stageInfo(trainingStage()),total=p.ids.reduce((n,id)=>n+target(id),0),saved=p.ids.reduce((n,id)=>n+Math.min(target(id),sets(id).length),0),fresh=!hasSessionStart(session)&&!complete,easy=returnToTraining(active(),selected)||(!active().some(r=>r.type==='session'&&r.data.status==='complete'))||profile.easyUntil>=selected;
 return heading('Your morning workout',complete?'Workout saved.':rest?'A day to recover.':p.name,`${info.name} · ${rest?'Easy activity or rest':p.kind==='Light day'?'About 30 minutes':'Aim for about 60 minutes'}`)+`<section class="card next-action"><h2>${complete?'You’re done for today.':rest?'Keep it comfortable.':fresh?'Ready when you are.':workoutNextLabel()}</h2><p>${complete?'Your next workout follows your weekly schedule.':rest?esc(p.reason||p.guidance||'Rest, or take an easy walk if you feel like it.'):'Warm up → train → cool down. Your place is saved.'}</p>${!rest&&!complete&&fresh?`<label class="easy-session"><input id="easy-session" type="checkbox" ${easy?'checked':''}> Easier session · first week or returning after a break</label>`:''}${button(complete?'View progress':rest?'View meals':fresh?'Start warm-up':esc(workoutNextLabel()),complete?'progress':rest?'food':'startsession')}<small>${!rest&&!complete?'Start light. Stop any movement that causes pain or tingling.':''}</small></section>${!rest?`<section class="card workout-outline"><div class="row"><h2>Today’s plan</h2><small>${saved}/${total} sets saved</small></div><ol>${p.ids.map(id=>`<li><span>${esc(exercises[id].name)}</span><small>${target(id)} ${id==='walk'?'walk':'sets'} · ${esc(exercises[id].repLabel)}</small></li>`).join('')}</ol><small>${p.kind==='Strength'?'5–8 min warm-up · 40–45 min strength · time to cool down.':'Gentle warm-up · 20 minutes easy cardio · cool down.'} Rest longer when needed.</small></section>`:''}<details class="card"><summary>This week & schedule</summary>${weekStrip()}<p>${planSummary(profile.workoutDays)}</p>${button('Calendar & time off','calendar','secondary')}</details><details class="card"><summary>Recovery check-in</summary><form data-form="checkin"><label>Sleep (hours)</label><input name="sleep" type="number" min="0" max="24" step="0.5" required><label>Energy</label><select name="energy"><option>Good</option><option>Low</option><option>Very low</option></select><label><input type="checkbox" name="symptom"> Pain or tingling today</label><p><button class="btn secondary">Save check-in</button></p></form><small>Optional. Recorded recovery helps you review progression.</small></details><p>${button('Food & meals','food','secondary')} ${button('My training journey','progress','secondary')}</p>${profile.pelvic?pelvic():''}`;
}
function equipmentGuide(id,runner){
 const e=exercises[id],state=equipment[id]||'unknown';
 const options=[['unknown','I don’t know yet'],['yes','Available'],['no','Unavailable']].map(([value,label])=>`<option value="${value}" ${state===value?'selected':''}>${label}</option>`).join('');
 const alternatives=e.alternatives.map(other=>`<p>${button('Use '+exercises[other].name,(runner?'substitute:':'guide:')+other,'secondary small')}<br><small>${equipment[other]==='no'?'Also marked unavailable. ':''}Review setup and symptoms first; log under its own name.</small></p>`).join('');
 return `<div class="equipment-guide"><p><strong>Equipment:</strong> ${e.equipment}</p>${toolStrip(e.tools)}<small>${e.evidence}</small><details><summary>Equipment availability & alternatives</summary><label for="equipment-${id}-${runner?'train':'guide'}">Available at my gym</label><select id="equipment-${id}-${runner?'train':'guide'}" data-equipment="${id}" aria-label="${e.name} equipment availability">${options}</select>${state==='unknown'?'<p class="notice">Not checked yet. Use the pictures or ask gym staff to find this equipment before training.</p>':''}${state==='no'?'<p class="notice">Station unavailable today. Use a suitable alternative or wait; avoid extra sets to compensate.</p>':''}<p><small>${id==='walk'?'Talk-test pace; 20–30 minutes or shorter easy bouts.':'Start light. Rest 90–120 seconds, longer if needed. Breathe throughout; exhale during the effort.'}</small></p>${alternatives?'<p><strong>Similar movements</strong></p>'+alternatives+'<small>Use instead of this slot, not as extra volume. Loads are not interchangeable.</small>':''}</details></div>`;
}
function gymGuide(){return `<section class="card"><div class="eyebrow">Your gym</div><h2>Get to know your equipment</h2><p>Use pictures and setup guides to identify machines. Ask gym staff if you are unsure, then mark each exercise’s equipment as available or unavailable.</p><small>Unknown is the default. Equipment choices sync with your own account.</small><p>${button('Review equipment & exercises','learn:equipment','secondary')}</p>${auth?.canClaimLegacy?`<details><summary>Your original gym reference</summary><p>${esc(gym.name)} · ${esc(gym.location)}</p><a href="${esc(gym.url)}" target="_blank" rel="noopener noreferrer">Gym listing ↗</a></details>`:''}</section>`;}
function pelvic(){return `<section class="card"><div class="row"><h2>Optional pelvic-floor practice</h2>${badge('Private · optional')}</div><p>Check suitability with a health professional first. Gently squeeze the pelvic-floor muscles, then fully relax. Breathe normally; avoid tightening thighs or abdomen. Do not routinely practise while urinating.</p><small>No automatic rep increases. Stop for pelvic discomfort or urinary difficulty.</small><p>${button('Log completed practice','pelvic','secondary')} <a href="https://www.niddk.nih.gov/health-information/urologic-diseases/kegel-exercises" target="_blank" rel="noopener">Read guidance ↗</a></p></section>`;}
function stageCard(){
 const review=stageReview(active(),selected,profile,qualifies),info=stageInfo(review.stage),next=stageInfo(review.next);
 return `<section class="card stage-overview"><div class="eyebrow">Your training journey</div><h2>${info.name}</h2><p>${info.focus}</p><details><summary>Beginner → Advanced roadmap</summary><ol class="stage-ladder">${trainingStages.map(stage=>`<li class="${stage.id===review.stage?'current-stage':''}"><strong>${stage.name}</strong><small>${stage.change}</small></li>`).join('')}</ol></details>${review.next?`<p>${review.count} / ${review.needed} qualifying workouts at this stage.</p><p>${review.ready?'Ready to review '+next.name+'. Your plan changes only after you confirm.':'Keep practising. A review opens after enough qualifying workouts and three recent controlled sessions.'}</p>${review.ready&&selected===dateKey()?button('Review '+next.name,'reviewstage','secondary'):''}`:'<p>Review exercise trends and fatigue. Advanced programming should be adjusted with a qualified trainer.</p>'}<details><summary>What counts for a review?</summary><p>Complete the recommended work, record controlled sets with at least two reps left, no symptoms or skipped movements, and a recovery check-in with good energy and 7+ hours’ sleep. Easier sessions stay in history but do not count toward advancement.</p><small>These are journal review prompts, not proof of fitness or automatic load increases. You can stay at a stage as long as you need.</small></details></section>`;
}
function train(){
 const p=plan(),session=sessionFor(active(),selected);
 if(p.skipped||selected>dateKey())return heading('Your session',p.skipped?'Take your planned break':'Preview your next workout',`${selected} · ${p.name}`)+`<section class="card"><p>${p.skipped?esc(p.reason):'Your guided session opens on this date. You can view the demonstrations now.'}</p>${button('View your week','calendar','secondary')}${button('Learn the movements','learn:exercises','secondary')}</section>`;
 if(!p.ids.length)return heading('Recovery day','Give yourself room to recover',selected)+`<section class="card"><p>Rest, or choose relaxed movement if comfortable. Your next training day starts with a guided warm-up.</p>${button('See my food plan','food')}${button('View my week','calendar','secondary')}</section>`;
 if(selected===dateKey()&&!hasSessionStart(session)&&session.status!=='complete')return heading('Your session','Ready to begin?',p.name)+`<section class="card"><p>Start your warm-up to begin timing your whole session, including exercises, rest and cooldown.</p>${button(session.warmupDone?'Start timer & resume workout':'Start warm-up','startsession')}</section>`;
 return renderCoach({advice:id=>exerciseAdvice(active(),selected,id,id==='assisted'?10:['raise','curl','bridge','calf','biceps','triceps'].includes(id)?15:id==='deadbug'?10:12,Math.max(target(id),recommendedSets(id,trainingStage()))),suggestion:id=>prescription(id,trainingStage(),active(),selected,session),state:coach(),session,p,stage:trainingStage(),selected,sets,target,button,video,reviewHTML:sessionReview(p),timerText,nextExercise:current()});
}
function sessionReview(p){const session=sessionFor(active(),selected);return `<details class="card"><summary>Review saved sets and skips</summary>${p.ids.map(id=>`<h3>${esc(exercises[id].name)}</h3>${sets(id).map(r=>`<div class="row list-item"><span>${id==='walk'?`${esc(r.data.minutes)} minutes`:`${esc(r.data.reps)} reps · ${esc(weightText(r.data))}`}<small>${r.data.symptom?' · Symptoms recorded':''}</small></span>${button('Undo set',`delete:${r.id}`,'secondary small')}</div>`).join('')}${(session.skippedExercises||[]).filter(r=>r.id===id).map(r=>`<p>Skipped · ${esc(r.reason)} ${button('Undo skip',`undoexercise:${id}`,'secondary small')}</p>`).join('')}`).join('')}</details>`;}
function dietaryForm(){return `<section class="card"><div class="eyebrow">Food choices & allergies</div><h2>Choose foods that work for you</h2><p>Adjust these examples for the foods you eat and avoid.</p><form data-form="dietary"><label>Foods you eat</label><select name="diet"><option value="any" ${mealProfile().diet==='any'?'selected':''}>Include eggs, fish and chicken</option><option value="vegetarian" ${mealProfile().diet==='vegetarian'?'selected':''}>Vegetarian</option><option value="vegan" ${mealProfile().diet==='vegan'?'selected':''}>Vegan</option></select><label>Foods to avoid (optional, separated by commas)</label><input name="avoid" maxlength="120" value="${esc(profile.avoid)}" placeholder="e.g. eggs, milk, wheat"><small>Ingredient checks are basic. Check every recipe and package for your restrictions.</small><p><button class="btn">Save food choices</button></p></form></section>`;}
function mealProfile(){return profile.diet?profile:{...profile,diet:'vegetarian'};}
function mealTimeline(){const logged=dayRecords().filter(r=>r.type==='food');return `<section class="card"><div class="eyebrow">Your food plan · ${selected}</div><h2>Your Bhubaneswar meal plan</h2><p>Familiar foods for Bhubaneswar, Odisha. Times and portions are examples. ${button('Food choices & allergies','dietary','secondary small')} Check ingredients for allergies and dietary restrictions.</p><fieldset class="diet-choices"><legend>Show meal examples</legend>${[['vegetarian','Vegetarian'],['any','With eggs / fish'],['vegan','Vegan']].map(([value,label])=>`<label><input type="radio" data-meal-diet value="${value}" name="meal-diet" ${mealProfile().diet===value?'checked':''}>${label}</label>`).join('')}</fieldset><p><small>${profile.diet?'Showing your food choices.':'Showing vegetarian examples to start. Choose another option above; no setup form needed.'}</small></p></section><div class="meal-timeline">${mealSlots.map(slot=>{const suggestion=suggestedMeal(slot,mealProfile(),meals,selected),m=suggestion||{name:'My suitable home meal',description:'',protein:0,kcal:0},row=logged.find(r=>r.data.slot===slot.id);return `<section class="card"><div class="row"><h3>${esc(row?.data.time||slot.time)} · ${slot.label}</h3>${badge(row?'Recorded':'Suggested')}</div>${row?`<p>${esc(row.data.name)} · ${esc(row.data.portion)}<br><small>Recorded for ${esc(row.data.time||slot.time)}</small></p>${button('Undo meal',`delete:${row.id}`,'secondary')}`:`<p><strong>${m.name}</strong><br>${suggestion?esc(m.description):'No suggested option matches these dietary needs. Enter a suitable meal below.'}</p>${suggestion?`<div class="food-sources"><p><strong>Protein comes from:</strong> ${esc(m.proteinSources)}</p><p><strong>Fibre comes from:</strong> ${esc(m.fiberSources)}</p></div><p class="muted">${esc(m.swap)}</p>${localMealOptions(slot,mealProfile()).length>1?`<label>Choose another local option</label><select data-meal-slot="${slot.id}">${localMealOptions(slot,mealProfile()).map((option,i)=>`<option value="${i}" ${option.name===m.name?'selected':''}>${esc(option.name)}</option>`).join('')}</select>`:''}`:''}<small>Edit the form below if you ate a different food or portion.</small><details><summary>Adjust time, meal or portion</summary><form data-form="plannedmeal" data-slot="${slot.id}"><label>Meal time</label><input type="time" name="time" value="${slot.time}" required><label>What you ate</label><input name="name" value="${esc(m.name)}" maxlength="100" required><label>Portions / ingredients</label><input name="portion" value="${esc(m.description)}" maxlength="200" required><div class="fields"><div><label>Estimated protein (g)</label><input type="number" name="protein" value="${m.protein}" min="0" max="300" step="0.1" required></div><div><label>Estimated energy (kcal)</label><input type="number" name="kcal" value="${m.kcal}" min="0" max="10000" required></div></div><p><button class="btn">Save what I ate</button></p></form></details>${suggestion?`<p>${button('I ate the suggested meal',`plannedmeal:${slot.id}`)}</p>`:''}<small>≈ ${m.protein} g protein · ≈ ${m.kcal} kcal; update estimates when swapping food.</small>`}</section>`;}).join('')}</div>`;}
function localFoodGuide(){return `<details class="card"><summary>Common protein and fibre foods around Bhubaneswar</summary><h3>Build the protein part of your plate</h3><p>Moong, arhar and masoor dal; cooked chana and peas; roasted chana; eggs; fish such as rohu; chicken; plain dahi, milk and chhena. Choose the foods that fit your diet.</p><h3>Add fibre and variety</h3><p>Dal and beans, saaga, santula and other vegetables, guava, papaya, seasonal fruit, and atta roti. Rice or chuda can be your grain portion; include dal and vegetables alongside them.</p><p>Examples: rice + dalma + saaga; or rice + machha jhola + vegetables. Plain chhena is different from sugar-rich chhena sweets.</p><small>Food-group guidance: <a href="https://www.nin.res.in/dietaryguidelines2024.html" target="_blank" rel="noopener noreferrer">ICMR–NIN ↗</a>. Local dishes: <a href="https://odishatourism.gov.in/en/cuisine-culinary-trails" target="_blank" rel="noopener noreferrer">Odisha Tourism ↗</a>.</small></details>`;}
function food(){const logged=dayRecords().filter(r=>r.type==='food');return heading('Bhubaneswar · Odisha','Eat familiar food. Fuel your day.','Follow your meal timeline and record what you ate. Times and portions can fit your day.')+mealTimeline()+localFoodGuide()+`<section class="card"><div class="row"><div><small>LOGGED PROTEIN</small><div class="big">${Math.round(sum(logged,'protein'))} <small style="font-size:16px">g</small></div></div><div><small>LOGGED ENERGY</small><div class="big">${Math.round(sum(logged,'kcal'))} <small style="font-size:16px">kcal</small></div></div></div><small>Household portions, cooking oil and recipes change these estimates. These are logged totals, not a prescribed calorie target.</small></section><details class="card"><summary>Your nutrition totals and trends</summary>${mealBreakdown(logged)}${foodTrend()}</details><details class="card"><summary>Other meal examples · check your dietary needs</summary><div class="grid">${meals.map((m,i)=>`<section class="card"><img class="meal-img" src="${m.img}" alt="${esc(m.description)} · AI-generated meal photo" width="480" height="358" loading="lazy"><small>AI-generated meal photo · portions are illustrative.</small><h3>${m.name}</h3><p>${m.description}</p>${badge('≈ '+m.protein+' g protein')}${badge('≈ '+m.kcal+' kcal')}<p>${button('Log this meal',`meal:${i}`,'secondary')}</p></section>`).join('')}</div></details><section class="card"><h2>Log your own food</h2><form data-form="food"><label>Meal / food</label><input name="name" required maxlength="100" placeholder="My lunch"><div class="fields"><div><label>Protein (g)</label><input name="protein" type="number" min="0" max="300" step="0.1" required></div><div><label>Energy (kcal)</label><input name="kcal" type="number" min="0" max="10000" required></div></div><label>Portion note</label><input name="portion" maxlength="200" placeholder="e.g. 150 g cooked fish"><p><button class="btn">Save meal</button></p></form></section><section class="card"><h2>Meals on ${selected}</h2>${logged.map(r=>`<div class="row list-item"><span>${esc(r.data.name)}<br><small>${esc(r.data.protein)} g protein · ${esc(r.data.kcal)} kcal · ${esc(r.data.portion)}</small></span>${button('Remove',`delete:${r.id}`,'secondary small')}</div>`).join('')||'<p class="empty">No meals logged yet.</p>'}</section>`;}
function mealBreakdown(logged){const total=sum(logged,'protein');return `<section class="card"><div class="eyebrow">Today · ${esc(selected)}</div><h2>Where your protein came from</h2>${logged.length?`<div class="ring-row">${ring(total,profile.protein,{label:'Protein logged on this day in grams',caption:`of ${profile.protein} g`})}<div>${hbars(logged.map(r=>({label:r.data.name,value:Number(r.data.protein)||0})),{unit:'g'})}</div></div><small>Each bar is one logged meal. Estimates, not exact values.</small>`:emptyChart('ring','Log a meal to see how each one adds to your protein goal.')}</section>`;}
function foodTrend(){const days=lastDays(14),foods=active().filter(r=>r.type==='food'),day=date=>foods.filter(r=>r.date===date),protein=days.map(date=>({label:date.slice(8),value:sum(day(date),'protein')})),energy=days.map(date=>({label:date.slice(8),value:sum(day(date),'kcal')}));return `<section class="card"><div class="eyebrow">Last 14 days</div><h2>Protein per day · g</h2>${protein.some(i=>i.value)?barChart(protein,{label:'Logged protein per day over the last 14 days',unit:'g',target:profile.protein})+'<small>Dark bars reached your goal. Days without records show as empty, not zero intake.</small>':emptyChart('bar','Log meals to see your daily protein compared with your goal.')}<h2>Energy per day · kcal</h2>${energy.some(i=>i.value)?barChart(energy,{label:'Logged energy per day over the last 14 days',unit:'kcal'})+'<small>Totals of recorded food only, not a calorie target.</small>':emptyChart('bar','Log meals to see your daily energy totals.')}</section>`;}
const kindKey=p=>p.skipped?'rest':p.kind==='Strength'?'lift':p.kind==='Light day'?'light':'rest';
const kindName=p=>p.skipped?'Skip':({lift:'Lift',light:'Light',rest:'Rest'})[kindKey(p)];
const kindPaths={lift:'<path d="M6 8v8M3 10v4M18 8v8M21 10v4M6 12h12"/>',light:'<path d="M12 20s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.6-7 10-7 10Z"/>',rest:'<path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5Z"/>'};
const kindIcon=p=>`<svg class="kind-icon" viewBox="0 0 24 24" aria-hidden="true">${kindPaths[kindKey(p)]}</svg>`;
function dayStatus(date){const rows=dayRecords(date);if(plan(date).skipped)return 'Skipped';if(rows.some(r=>r.type==='session'&&r.data.status==='skipped'))return 'Skipped';if(rows.some(r=>r.type==='session'&&r.data.status==='complete'))return 'Complete';if(rows.some(r=>r.type==='set'||r.type==='session'&&r.data.status==='in_progress'))return 'Partial';return 'Not logged';}
function monthSummary(y,m,count){const today=dateKey(),days=Array.from({length:count},(_,i)=>dateKey(new Date(y,m,i+1))).filter(d=>d<=today),planned=days.filter(d=>plan(d).kind!=='Recovery'),status=planned.map(dayStatus),done=status.filter(s=>s==='Complete').length,title=month.toLocaleDateString(undefined,{month:'long'});return `<section class="card"><div class="eyebrow">${esc(title)} so far</div><h2>Planned activity days</h2>${planned.length&&status.some(s=>s!=='Not logged')?`<div class="ring-row">${ring(done,planned.length,{label:`Completed activity days in ${title}`,caption:`of ${planned.length} days`})}<div>${hbars(['Complete','Partial','Skipped','Not logged'].map(label=>({label,value:status.filter(s=>s===label).length})),{unit:'days'})}</div></div><small>Counts only past and current days that the plan marks as Lift or Light. ${days.length-planned.length} rest days are not counted.</small>`:emptyChart('ring',planned.length?'Log a session this month to see completed, partial and skipped days.':'This month has not started yet.')}</section>`;}
function breakPanel(){const breaks=active().filter(r=>r.type==='break').sort((a,b)=>b.date.localeCompare(a.date));return `<section class="card"><h2>Plan time off</h2><p>Skip one day or a date range for travel, meetings or rest. Your normal weekly schedule resumes afterwards; completed workouts and other logs stay saved.</p><form data-form="break"><div class="fields"><div><label>First day</label><input name="start" type="date" min="${dateKey()}" value="${selected<dateKey()?dateKey():selected}" required></div><div><label>Last day (same date for one day)</label><input name="end" type="date" min="${dateKey()}" value="${selected<dateKey()?dateKey():selected}" required></div></div><label>Reason</label><select name="reason"><option>Travel</option><option>Work / meetings</option><option>Rest / recovery</option><option>Other plans</option></select><p><button class="btn secondary">Save break</button></p></form>${breaks.map(r=>`<div class="list-item"><strong>${r.date} → ${esc(r.data.endDate)}</strong><p>${esc(r.data.reason)} ${button('Cancel break','cancelbreak:'+r.id,'secondary small')}</p></div>`).join('')}<small>After a break, use an easier first session. Do not double up to catch up.</small></section>`;}
async function removeScheduleRecords(rows){const epoch=accountEpoch;const deleted=rows.map(r=>({...r,deleted:true,dirty:true,updatedAt:new Date().toISOString()}));await putMany(deleted);if(epoch!==accountEpoch)return;for(const r of deleted)Object.assign(records.find(x=>x.id===r.id),r);render();toast('Schedule updated; any other breaks still apply');if(auth)sync(false);}
async function saveBreak(start,end,reason){const epoch=accountEpoch,row={...makeRecord('break',start,{endDate:end,reason:String(reason).slice(0,160)})};await putMany([row]);if(epoch!==accountEpoch)return;records.push(row);render();toast('Break saved; your normal schedule resumes afterwards');if(auth)sync(false);}
function calendar(){const y=month.getFullYear(),m=month.getMonth(),count=new Date(y,m+1,0).getDate(),offset=(new Date(y,m,1).getDay()+6)%7;return heading('Your rhythm','A week with room to recover.',planSummary(profile.workoutDays))+`<section class="card"><div class="row"><h2>${month.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><div>${button('←','month:-1','secondary small')} ${button('→','month:1','secondary small')}</div></div><div class="calendar">${['M','T','W','T','F','S','S'].map(x=>`<small style="text-align:center">${x}</small>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const key=dateKey(new Date(y,m,i+1)),logged=dayRecords(key).length,p=plan(key);return `<button data-action="date:${key}" class="kind-${kindKey(p)} ${selected===key?'selected':''} ${logged?'logged':''}" aria-label="${key}, ${p.name}, ${logged} records">${i+1}${kindIcon(p)}<small>${logged?'● ':''}${kindName(p)}</small></button>`;}).join('')}</div><p class="legend">${['Strength','Light day','Recovery'].map(kind=>`<span class="legend-item kind-${kindKey({kind})}">${kindIcon({kind})}${kindName({kind})}</span>`).join('')} · Purple border: records saved</p></section>${monthSummary(y,m,count)}${breakPanel()}<section class="card"><h2>${selected} · ${plan().name}</h2><p>${dayRecords().length} records saved. ${dayRecords().some(r=>r.type==='session'&&r.data.status==='complete')?'Session marked complete.':'Session not marked complete.'}</p>${button('Open this day','train')} ${button('Log food','food','secondary')} ${plan().skipped?button('Undo skipped day','unskip','secondary'):button('Skip this day','skip','secondary')}<form data-form="schedule"><label>Change this day’s plan</label><select name="day">${[1,2,3,4,5,0].map(i=>`<option value="${i}" ${plan().name===week[i].name?'selected':''}>${week[i].name}</option>`).join('')}</select><p><button class="btn secondary">Save day plan</button></p></form><small>Use this to move sessions around travel or work. Preserve recovery days; do not stack missed workouts.</small><div>${dayRecords().map(r=>`<div class="list-item">${esc(r.type)} · ${esc(r.data.name||exercises[r.data.exercise]?.name||r.data.note||'Recorded')} ${r.data.reps?`· ${esc(r.data.reps)} reps`:''}</div>`).join('')}</div></section><section class="card"><h2>Your weekly plan</h2>${[1,2,3,4,5,6,0].map(i=>`<div class="row list-item"><span>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]}</span><strong>${weeklyPlan(profile.workoutDays)[i].name}</strong></div>`).join('')}<p><a download="stride-week.ics" href="${calendarFile()}">Export next week to your calendar ↗</a></p><small>Calendar notifications are controlled by your calendar app.</small></section>`;}
function trend(rows,key,label,unit){const points=rows.filter(r=>Number.isFinite(Number(r.data[key]))&&r.data[key]!==null).sort((a,b)=>a.date.localeCompare(b.date)||a.updatedAt.localeCompare(b.updatedAt)).map(r=>({x:r.date.slice(5),y:Number(r.data[key])}));return points.length<2?emptyChart('line','Log at least two measurements to see a trend.'):lineChart(points,{label,unit});}
function consistency(a){const start=new Date();start.setDate(start.getDate()-((start.getDay()+6)%7)-77);const days=Array.from({length:84},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const date=dateKey(d),rows=a.filter(r=>r.date===date),complete=rows.some(r=>r.type==='session'&&r.data.status==='complete'),lifted=rows.some(r=>r.type==='set');return {date,level:complete?3:lifted?2:rows.length?1:0,title:complete?'Session complete':lifted?'Sets logged':rows.length?`${rows.length} records`:'No records'};}).filter(d=>d.date<=dateKey());return `<section class="card"><div class="eyebrow">Last 12 weeks</div><h2>Consistency</h2><div class="scroll">${heatmap(days)}</div><small>Each square is a day, Monday to Sunday down each column. Darkest: session marked complete.</small></section>`;}
function weeklyVolume(lift){const monday=d=>{const x=fromDate(d);x.setDate(x.getDate()-((x.getDay()+6)%7));return dateKey(x);},now=monday(dateKey()),weeks=Array.from({length:8},(_,i)=>{const d=fromDate(now);d.setDate(d.getDate()-(7-i)*7);return dateKey(d);});const items=weeks.map(w=>({label:w.slice(5).replace('-','/'),parts:patterns.map(([p])=>lift.filter(r=>monday(r.date)===w&&exercises[r.data.exercise]?.pattern===p).length)}));const thisWeek=lift.filter(r=>monday(r.date)===now),plannedFor=p=>Array.from({length:7},(_,i)=>{const d=fromDate(now);d.setDate(d.getDate()+i);return plan(dateKey(d));}).reduce((t,d)=>t+d.ids.filter(id=>exercises[id].pattern===p).reduce((n,id)=>n+target(id),0),0);return `<section class="card"><div class="eyebrow">Last 8 weeks</div><h2>Working sets per week</h2>${lift.some(r=>exercises[r.data.exercise]?.pattern!=='cardio')?stackedBars(items,patterns.map(p=>p[1]),{label:'Logged working sets per week by movement pattern',unit:'sets'}):emptyChart('bar','Log strength sets to see weekly training volume.')}<h3>This week vs plan</h3>${hbars(patterns.map(([p,label])=>({label,value:thisWeek.filter(r=>exercises[r.data.exercise]?.pattern===p).length,target:plannedFor(p)})),{unit:'sets'})}<small>Planned sets come from your weekly schedule and training stage. Muscle groups are grouped by movement pattern.</small></section>`;}
function exerciseTrend(lift){const ids=Object.keys(exercises).filter(id=>lift.some(r=>r.data.exercise===id));if(!ids.length)return `<section class="card"><h2>Exercise trends</h2>${emptyChart('line','Log sets to chart load and volume for each exercise.')}</section>`;if(!ids.includes(trendExercise))trendExercise=ids[0];const rows=lift.filter(r=>r.data.exercise===trendExercise),dates=[...new Set(rows.map(r=>r.date))].sort().slice(-10),cardio=trendExercise==='walk',body=!cardio&&rows.every(r=>!r.data.weight),per=dates.map(date=>{const day=rows.filter(r=>r.date===date);return {x:date.slice(5),top:cardio?sum(day,'minutes'):body?Math.max(...day.map(r=>r.data.reps)):Math.max(...day.map(r=>r.data.weight)),volume:cardio?sum(day,'minutes'):day.reduce((n,r)=>n+r.data.reps*(r.data.weight||1),0)};});const topLabel=cardio?'Minutes':body?'Best set (reps)':rows.some(r=>r.data.assistance)?'Assistance (kg, lower is harder)':'Heaviest set (kg)';return `<section class="card"><div class="eyebrow">Exercise trends</div><label for="trend-exercise">Exercise</label><select id="trend-exercise">${ids.map(id=>`<option value="${id}" ${id===trendExercise?'selected':''}>${exercises[id].name}</option>`).join('')}</select><h3>${topLabel}</h3>${per.length>1?lineChart(per.map(p=>({x:p.x,y:p.top})),{label:`${exercises[trendExercise].name} ${topLabel}`,unit:cardio?'min':body?'reps':'kg'}):emptyChart('line','Log this exercise on a second day to see a trend.')}${cardio?'':`<h3>Session volume ${info('volume')}</h3>${barChart(per.map(p=>({label:p.x,value:p.volume})),{label:`${exercises[trendExercise].name} volume per session`,unit:body?'reps':'kg × reps'})}`}<small>Compare only sessions on the same machine and setting.</small></section>`;}
function recovery(a){const days=lastDays(14),checks=a.filter(r=>r.type==='checkin');if(!checks.length)return `<section class="card"><h2>Sleep & energy</h2>${emptyChart('bar','Save a check-in on the Today screen to see sleep and energy trends.')}</section>`;const latest=date=>checks.filter(r=>r.date===date).sort((x,y)=>y.updatedAt.localeCompare(x.updatedAt))[0];const items=days.map(date=>({label:date.slice(8),value:Number(latest(date)?.data.sleep)||0}));const recent=days.map(latest).filter(Boolean);return `<section class="card"><div class="eyebrow">Last 14 days</div><h2>Sleep · hours</h2>${barChart(items,{label:'Sleep hours from check-ins over the last 14 days',unit:'h',target:7})}<h3>Energy check-ins</h3>${hbars(['Good','Low','Very low'].map(level=>({label:level,value:recent.filter(r=>r.data.energy===level).length})),{unit:'days'})}<small>${recent.filter(r=>r.data.symptom).length} check-ins reported arm or wrist symptoms.</small></section>`;}
function progress(){const a=active(),measure=a.filter(r=>r.type==='measurement'),sessions=a.filter(r=>r.type==='session'&&r.data.status==='complete'),lift=a.filter(r=>r.type==='set'),days=new Set(lift.map(r=>r.date)).size;return heading('Your learning journey','Your progress','Build consistency, one guided workout at a time.')+stageCard()+sessionHistory()+`<div class="progress-facts"><section><strong>${new Set(sessions.map(r=>r.date)).size}</strong><span>Workouts completed</span></section><section><strong>${lift.length}</strong><span>Sets and walks saved</span></section></div>${sessions.length?weeklyReport(a):`<section class="card"><h2>Your first milestone</h2><p>Finish your first guided workout. Your completed sessions and learning progress will appear here.</p>${button('Continue my workout','train')}</section>`}${lift.length?`<details class="card"><summary>Training history and charts</summary>${consistency(a)}${weeklyVolume(lift)}${days>=2?exerciseTrend(lift):'<p>Complete workouts on two different days to unlock exercise trends.</p>'}<section class="card"><h2>Exercise history</h2><div class="scroll"><table><thead><tr><th>Date</th><th>Exercise</th><th>Result</th><th>Form / symptoms</th></tr></thead><tbody>${lift.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,50).map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(exercises[r.data.exercise]?.name||r.data.exercise)}</td><td>${r.data.minutes?`${esc(r.data.minutes)} min`:`${esc(r.data.reps)} reps · ${esc(weightText(r.data))}`}</td><td>${esc(r.data.symptom?'Stop / assess':r.data.form||'—')}</td></tr>`).join('')}</tbody></table></div>${lift.length?'':'<p class="empty">Start logging to build your history.</p>'}</section><section class="card"><h2>Next-session guidance</h2>${Object.keys(exercises).filter(id=>lift.some(r=>r.data.exercise===id)).map(id=>{const rows=lift.filter(r=>r.data.exercise===id).sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt.localeCompare(a.updatedAt)),latest=rows.filter(r=>r.date===rows[0].date);const caution=latest.some(r=>r.data.symptom||r.data.form!=='good');return `<p><strong>${exercises[id].name}:</strong> ${caution?'Repeat or reduce only when symptom-free; do not increase. Ask for technique/clinical guidance as appropriate.':latest.length>=2&&latest.every(r=>r.data.reps>=(id==='assisted'?10:Number(exercises[id].reps.match(/–(\d+)/)?.[1]||12))&&r.data.rir>=2)?(latest.some(r=>r.data.assistance)?'If all prescribed sets reached the upper rep limit with control, consider the smallest reduction in assistance.':'If all prescribed sets reached the upper rep limit with control, consider the smallest suitable load increase.'):'Keep the load manageable and build clean repetitions within the prescribed range.'}</p>`;}).join('')||'<p class="muted">Suggestions appear after you record workouts.</p>'}</section></details>`:''}<details class="card"><summary>Body measurements and recovery</summary>${measure.length>=2?`<section><h2>Body weight · kg</h2>${trend(measure,'weight','Body weight in kilograms','kg')}</section>`:''}${measure.filter(r=>r.data.waist).length>=2?`<section><h2>Waist · cm</h2>${trend(measure.filter(r=>r.data.waist),'waist','Waist in centimetres','cm')}</section>`:''}${a.filter(r=>r.type==='checkin').length?recovery(a):''}<p>Measurements are optional. Two recorded days are needed to show a trend.</p><form data-form="measurement"><div class="fields"><div><label>Body weight (kg)</label><input name="weight" type="number" min="25" max="400" step="0.1" value="${esc(profile.weight)}" required></div><div><label>Waist (cm, optional)</label><input name="waist" type="number" min="30" max="250" step="0.1"></div></div><p><button class="btn">Save measurement</button></p></form></details>`;}
function weeklyReport(rows){const dates=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return dateKey(d);});const days=dates.map(date=>({date,rows:rows.filter(r=>r.date===date),plan:plan(date)}));const planned=days.filter(d=>d.plan.kind!=='Recovery').length,complete=days.filter(d=>d.rows.some(r=>r.type==='session'&&r.data.status==='complete')&&d.plan.kind!=='Recovery').length;const foods=days.filter(d=>d.rows.some(r=>r.type==='food'));return `<section class="card"><div class="eyebrow">Last seven days</div><h2>${complete} / ${planned} planned activity days completed</h2><div class="bar"><i style="width:${planned?complete/planned*100:0}%"></i></div><p>${foods.length?`${Math.round(foods.reduce((n,d)=>n+sum(d.rows.filter(r=>r.type==='food'),'protein'),0)/foods.length)} g average logged protein on ${foods.length} food-logged days.`:'No meal records in this period.'}</p><div class="scroll"><table><thead><tr><th>Date</th><th>Session</th><th>Logged protein</th></tr></thead><tbody>${days.map(d=>`<tr><td>${d.date.slice(5)}</td><td>${d.plan.skipped||d.rows.some(r=>r.type==='session'&&r.data.status==='skipped')?'Skipped':d.rows.some(r=>r.type==='session'&&r.data.status==='complete')?'Complete':d.plan.kind==='Recovery'?'Rest':d.rows.some(r=>r.type==='set'||r.type==='session'&&r.data.status==='in_progress')?'Partial':'Not logged'}</td><td>${d.rows.some(r=>r.type==='food')?Math.round(sum(d.rows.filter(r=>r.type==='food'),'protein'))+' g':'—'}</td></tr>`).join('')}</tbody></table></div><small>Missing meal records are not zero intake. Completion is based on your session check-off.</small></section>`;}
function settings(){return heading('Your app','Learn, plan and manage','Keep the essentials close. Other options are here when you need them.')+`${installCard()}<details class="card"><summary>Gym equipment references</summary>${gymGuide()}<p>Reference models and Indian creator demonstrations help identify a movement. Confirm the exact machine, attachment and settings with staff.</p></details><section class="card"><h2>Learning</h2><div class="more-links">${button('Beginner guide & exercise library','learn','secondary')}${button('Equipment and setup','learn:equipment','secondary')}</div></section><section class="card"><h2>Schedule</h2><p>Your week includes training and recovery.</p>${button('Calendar & time off','calendar','secondary')}</section><details class="card"><summary>Schedule and personal details</summary><form data-form="profile">${frequencyField(profile)}<div class="fields"><div><label>Body weight (kg, optional)</label><input name="weight" type="number" min="25" max="400" step="0.1" value="${esc(profile.weight)}"></div><div><label>Height (cm, optional)</label><input name="height" type="number" min="100" max="250" value="${esc(profile.height)}"></div><div><label>Protein goal (g)</label><input name="protein" type="number" min="40" max="250" value="${esc(profile.protein)}" required></div></div><p>Your stage is guided by your saved sessions. See Progress for your learning journey.</p><label><input name="pelvic" type="checkbox" ${profile.pelvic?'checked':''}> Show optional pelvic-floor guidance and logging</label><p><button class="btn">Save preferences</button></p></form><small>Your routine starts with beginner guidance. Review stage changes in Progress.</small></details>${accountPanel({auth:auth||(!isOnline()&&cachedAccount?{user:cachedAccount}:null),cloudReady,emailReady,googleReady,mode:authMode,message:authMessage,resetToken})}<details class="card"><summary>Backup and storage</summary><p>${button('Export backup','export','secondary')} ${button('Keep journal on this device','persist','secondary')}</p><label>Import backup (merges with your records)</label><input id="import" type="file" accept="application/json,.json"><p><small>Exports contain private health records. Store them securely. Browser storage can be cleared; sync does not replace recovery backups.</small></p></details><details class="card"><summary>Reminders</summary><p>The rest timer can notify you while the workout screen is active. Export your week to your phone calendar for scheduled reminders.</p>${button('Open calendar','calendar','secondary')}<small>For exact alarms, use your phone Clock.</small></details><details class="card"><summary>References and teaching media</summary>${sources.map(([name,url])=>`<p><a href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a></p>`).join('')}<p class="muted">Generated teaching images and reference photos may show different models from your gym. Use the demonstration and ask staff about your machine settings. Demonstration videos are third-party YouTube content and need an internet connection.</p></details>`;}
function syncStatus(){const pending=records.filter(r=>r.dirty).length;if(!auth&&!cachedAccount)return isOnline()?'Saved on this device':'Offline · saved here';return !isOnline()?'Offline · saved here':pending?`Saved here · ${pending} waiting to sync`:lastSync?'Saved and synced':'Saved on this device';}
function learn(){const sections={basics:()=>`<div class="grid">${basics.map(b=>`<section class="card" id="basic-${b.id}"><h3>${b.term}</h3><p><strong>${b.short}</strong></p>${basicsVisual(b.id,`${b.term}: ${b.short}`)}<p>${b.detail}</p>${basicReference(b.id)}</section>`).join('')}</div><small>Sources: ACSM progression guidance and the repetitions-in-reserve RPE scale, linked in Settings.</small>`,equipment:()=>`${[1,2,3,4,5].map(i=>`<section class="card"><div class="row"><h3>${['','Monday','Tuesday','Wednesday','Thursday','Friday'][i]} · ${week[i].name}</h3>${badge(dayTools(week[i]).length+' items')}</div>${toolStrip(dayTools(week[i]))}</section>`).join('')}<h2>All equipment</h2><div class="grid">${Object.keys(tools).map(id=>`<section class="card"><h3>${tools[id].name}</h3>${toolDetail(id,Object.keys(exercises).filter(x=>exercises[x].tools.includes(id)))}</section>`).join('')}</div>`,exercises:()=>`<label>Find an exercise</label><input id="search" placeholder="Name or muscle group" value="${esc(exerciseFilter)}"><div id="library-results">${libraryResults()}</div>`};return heading('Learn','Know the words. Know the tools.','Training terms, every machine in your plan, and each movement with a demonstration video.')+`<div class="segmented">${[['basics','Basics'],['equipment','Equipment'],['exercises','Exercises']].map(([id,label])=>`<button data-action="learn:${id}" class="${learnSection===id?'active':''}" aria-pressed="${learnSection===id}">${label}</button>`).join('')}</div>${sections[learnSection]()}`;}
function workoutDraftKey(form){return draftKey(form.dataset.draftScope||scope,form.dataset.draftDate||selected,form.dataset.exercise,form.dataset.setIndex||1);}
function rememberWorkout(){const f=document.querySelector('.coach-log');if(!f)return;const data={};for(const input of f.elements){if(!input.name||input.value==='more')continue;if(input.type==='radio'){if(input.checked)data[input.name]=input.value;}else data[input.name]=input.type==='checkbox'?input.checked:input.value;}writeDraft(sessionStorage,workoutDraftKey(f),data);}
function updateSetPlan(f){const card=f.closest('.coach-step'),dose=card?.querySelector('[data-set-plan]'),total=f.elements.sets?.value;if(!dose||!total)return;dose.textContent='Your plan: '+total+(f.elements.minutes?' walk × '+f.elements.minutes.value+' minutes':' sets × '+f.elements.reps.value+' reps'+(dose.dataset.perSide==='true'?' per side':''));const counter=card.querySelector('[data-set-total]');if(counter)counter.textContent=total;}
function restoreWorkout(){const f=document.querySelector('.coach-log');if(!f)return;f.dataset.draftScope=scope;f.dataset.draftDate=selected;const data=readDraft(sessionStorage,workoutDraftKey(f));if(!data)return;for(const input of f.elements){if(!(input.name in data))continue;const value=data[input.name];if(input.type==='radio')input.checked=input.value===value;else if(input.type==='checkbox')input.checked=!!value;else{if(input.tagName==='SELECT'&&!Array.from(input.options).some(o=>o.value===String(value))){const allowed=JSON.parse(input.dataset.choiceOptions||'[]').find(o=>o.value===String(value));if(allowed)input.add(new Option(allowed.label,allowed.value));else continue;}input.value=value;if(input.dataset.choiceOptions)input.dataset.choiceCurrent=value;}}updateSetPlan(f);}
function inlineError(form,message){form.querySelector('[data-form-error]')?.remove();const error=document.createElement('p');error.dataset.formError='true';error.className='form-error';error.setAttribute('role','alert');error.tabIndex=-1;error.textContent=message;form.prepend(error);error.focus();}
function runningSession(){return active().filter(r=>r.type==='session'&&hasSessionStart(r.data)&&!r.data.endedAt&&!['complete','skipped'].includes(r.data.status)).sort((a,b)=>b.data.startedAt.localeCompare(a.data.startedAt))[0];}
function sessionClock(){const running=runningSession(),row=running||dayRecords().find(r=>r.type==='session'&&hasSessionStart(r.data));if(!row)return '';const timing=row.data,seconds=sessionSeconds(timing);return `<aside class="session-clock" aria-label="Workout session time"><div><span>${timing.endedAt?'Total session time':'Session time · running'}</span><strong ${timing.endedAt?'':'data-session-clock'}>${durationText(seconds)}</strong><small>Started ${esc(new Date(timing.startedAt).toLocaleString())}${timing.endedAt?` · Ended ${esc(new Date(timing.endedAt).toLocaleString())}`:' · Includes rest and breaks'}</small></div>${running&&(tab!=='train'||selected!==row.date)?button('Resume workout','resumesession:'+row.date,'secondary small'):''}</aside>`;}
function sessionHistory(){const timed=active().filter(r=>r.type==='session'&&hasSessionStart(r.data)&&r.data.endedAt).sort((a,b)=>b.data.startedAt.localeCompare(a.data.startedAt)).slice(0,50);if(!timed.length)return '';return `<section class="card session-history"><h2>Time spent training</h2><p>Total session time includes warm-up, rest, exercises and cooldown.</p>${timed.map(r=>`<div class="list-item"><div class="row"><strong>${esc(r.date)} · ${esc(r.data.name||'Workout')}</strong><strong>${durationText(sessionSeconds(r.data))}</strong></div><small>${r.data.status==='complete'?'Completed':'Stopped / edited'} · Started ${esc(new Date(r.data.startedAt).toLocaleString())} · Ended ${esc(new Date(r.data.endedAt).toLocaleString())}</small></div>`).join('')}</section>`;}
function render(){rememberWorkout();if(tab==='train'&&coach().phase==='rest'){const deadline=coach().row.data.restUntil;timerEnd=deadline>Date.now()?deadline:0;}syncNavigation();const offlineAccount=!isOnline()&&cachedAccount&&scope===`account-${cachedAccount.id}`&&!localStorage.getItem('form-pending-signout');const accountOnly=!!resetToken||(!auth&&!offlineAccount&&(checkingAccount||cloudReady||cloudAccountRequired||scope!=='guest'));if(accountOnly){$('#app').innerHTML=`<a class="skip-link" href="#main-content">Skip to main content</a><main id="main-content" tabindex="-1"><header><div class="brand"><img src="./form-brand-64.png" width="32" height="32" alt=""><div>STRIDE<span>YOUR TRAINING JOURNAL</span></div></div></header>${checkingAccount?'<section class="card" role="status"><h2>Opening your account…</h2><p>Checking your saved session.</p></section>':accountPanel({auth:null,cloudReady,emailReady,googleReady,mode:authMode,message:authMessage,resetToken})}</main>`;}else{const views={today,train,food,calendar,progress,settings,learn};$('#app').innerHTML=`<a class="skip-link" href="#main-content">Skip to main content</a><main id="main-content" tabindex="-1"><header><div class="brand"><img src="./form-brand-64.png" width="32" height="32" alt=""><div>STRIDE<span>${esc(auth?.user.name||cachedAccount?.name||'YOUR LOCAL JOURNAL')}</span></div></div><button class="status" data-action="settings">${esc(syncStatus())}</button></header>${sessionClock()}${tab!=='today'?`<div class="page-links">${button('← Back','back','secondary small')}${button('Today','today','secondary small')}${tab==='train'?button('Calendar & day plan','calendar','secondary small'):''}</div>`:''}${!auth&&scope==='guest'&&tab==='today'&&cloudReady?`<section class="card"><h2>Your own training journal</h2><p>Sign in to keep your workouts and progress separate and sync across devices.</p>${button('Sign in','authmode:signin')} ${button('Sign up','authmode:signup','secondary')}</section>`:''}${profile.guideVersion!==22?onboarding(profile):''}${scope!=='guest'&&!auth&&isOnline()?accountPanel({auth:null,cloudReady,emailReady,googleReady,mode:authMode,message:authMessage,resetToken}):profile.guideVersion===22?views[tab]():''}<footer>One good session at a time · ${isOnline()?'Online':'Offline'} · logging for ${selected}</footer></main><nav aria-label="Main navigation">${[['today','Today'],['train','Train'],['food','Food'],['progress','Progress'],['settings','More']].map(([id,label])=>`<button data-action="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><b aria-hidden="true">${navIcon(id)}</b>${label}</button>`).join('')}</nav>`;}document.querySelectorAll('label').forEach((label,i)=>{const control=label.nextElementSibling;if(control?.matches('input,select')){control.id||=`field-${i}`;label.htmlFor=control.id;}});restoreWorkout();const cloudStatus=$('#cloud-status');if(cloudStatus)cloudStatus.textContent=syncStatus();}
function libraryResults(){return Object.keys(exercises).filter(id=>(exercises[id].name+' '+exercises[id].muscles).toLowerCase().includes(exerciseFilter.toLowerCase())).map(id=>exerciseCard(id)).join('')||'<p class="empty">No matching exercise.</p>';}
async function save(type,data){const epoch=accountEpoch,row=makeRecord(type,selected,data);await putMany([row]);if(epoch!==accountEpoch)return;records.push(row);render();toast('Saved on phone');if(isOnline()&&auth)sync(false);}
async function saveDaily(type,data){const existing=dayRecords().find(r=>r.type===type);if(!existing)return save(type,data);const epoch=accountEpoch;Object.assign(existing,{data,dirty:true,updatedAt:new Date().toISOString()});await putMany([existing]);if(epoch!==accountEpoch)return;render();toast('Day updated');if(auth)sync(false);}
function timerText(){const s=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;}
setInterval(()=>{const clock=$('[data-session-clock]'),running=runningSession();if(clock&&running)clock.textContent=durationText(sessionSeconds(running.data));if($('#timer'))$('#timer').textContent=timerText();if(timerEnd&&Date.now()>=timerEnd){timerEnd=0;toast('Rest finished — start when ready');navigator.vibrate?.([150,80,150]);try{const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);g.gain.value=.08;o.start();o.stop(c.currentTime+.2);o.onended=()=>c.close();}catch{}if(tab==='train'&&coach().phase==='rest')render();}},500);
function calendarFile(){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Stride//Training//EN'];for(let i=0;i<7;i++){const d=new Date();d.setDate(d.getDate()+i);const k=dateKey(d).replaceAll('-',''),next=new Date(d);next.setDate(next.getDate()+1);lines.push('BEGIN:VEVENT',`UID:${k}-form`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;VALUE=DATE:${k}`,`DTEND;VALUE=DATE:${dateKey(next).replaceAll('-','')}`,`SUMMARY:Stride - ${plan(dateKey(d)).name}`,'END:VEVENT');}lines.push('END:VCALENDAR');return 'data:text/calendar;charset=utf-8,'+encodeURIComponent(lines.join('\r\n'));}
let appRegistration=null,updateRequested=false;
