async function registerAppWorker(){try{appRegistration=await navigator.serviceWorker.register('./sw.js');offerAppUpdate();appRegistration.addEventListener('updatefound',()=>{const worker=appRegistration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed')offerAppUpdate();});});}catch{toast('Offline cache unavailable. Use HTTPS or localhost.');}}
if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('controllerchange',()=>{$('#app-update')?.remove();if(updateRequested)location.reload();});
let journalWriting=false;
let installPrompt,appInstalled=false;
const standaloneDisplay=matchMedia('(display-mode: standalone)');
