function installCard(){return `<section class="card" id="app-install"><h2>App on your home screen</h2>${installedApp()?'<p>Stride is running as an installed app.</p>':`<p>Open Stride from your home screen and keep your loaded journal available offline.</p>${button(installPrompt?'Install Stride':'How to install','install','secondary')}<p class="muted">${isSecureContext?'Use Chrome on Android or Safari on iPhone. If this link opened inside another app, open it in your browser first.':'Open the public HTTPS address on your phone to enable PWA installation. A plain HTTP network address cannot install this app.'}</p>`}</section>`;}
