function installHelp(){showDialog(`<h2>Add Stride to your home screen</h2>${!isSecureContext?'<p>First open the public HTTPS address. Installation and offline caching need a secure connection.</p>':''}<h3>Android</h3><p>Open this address directly in Chrome. Tap the three-dot menu, then Add to home screen or Install app. Follow the confirmation.</p><h3>iPhone / iPad</h3><p>Open this address in Safari. Tap Share, then Add to Home Screen. Turn on Open as Web App if offered, then tap Add. If the action is missing, scroll down to Edit Actions and add it.</p><p>If you opened the link inside WhatsApp, Gmail, Instagram or another app, use its Open in browser option or copy the address into Chrome or Safari.</p>`,'Install Stride');}
